import { extend } from '@vue/shared'
import type { ComputedRefImpl } from './computed'
import { type TrackOpTypes, TriggerOpTypes } from './constants'
import {
  type DebuggerEventExtraInfo,
  EffectFlags,
  type Link,
  ReactiveEffect,
  activeSub,
  endBatch,
  shouldTrack,
  startBatch,
} from './effect'

/**
 * Incremented every time a reactive change happens
 * This is used to give computed a fast path to avoid re-compute when nothing
 * has changed.
 */
export let globalVersion = 0

export function incrementGlobalVersion(): number {
  globalVersion++
  return globalVersion
}

/**
 * @internal
 */
export class Dep {
  version = 0
  /**
   * Link between this dep and the current active effect
   */
  activeLink?: Link = undefined

  /**
   * Doubly linked list representing the subscribing effects (tail)
   */
  subs?: Link = undefined

  /**
   * Doubly linked list representing the subscribing effects (head)
   * DEV only, for invoking onTrigger hooks in correct order
   */
  subsHead?: Link

  constructor(public computed?: ComputedRefImpl | undefined) {
    if (__DEV__) {
      this.subsHead = undefined
    }
  }

  track(debugInfo?: DebuggerEventExtraInfo): Link | undefined {
    if (!activeSub || !shouldTrack) {
      return
    }

    let link = this.activeLink
    if (link === undefined || link.sub !== activeSub) {
      link = this.activeLink = {
        dep: this,
        sub: activeSub,
        version: this.version,
        nextDep: undefined,
        prevDep: undefined,
        nextSub: undefined,
        prevSub: undefined,
        prevActiveLink: undefined,
      }

      // add the link to the activeEffect as a dep (as tail)
      if (!activeSub.deps) {
        activeSub.deps = activeSub.depsTail = link
      } else {
        link.prevDep = activeSub.depsTail
        activeSub.depsTail!.nextDep = link
        activeSub.depsTail = link
      }

      if (activeSub.flags & EffectFlags.TRACKING) {
        addSub(link)
      }
    } else if (link.version === -1) {
      // reused from last run - already a sub, just sync version
      link.version = this.version

      // If this dep has a next, it means it's not at the tail - move it to the
      // tail. This ensures the effect's dep list is in the order they are
      // accessed during evaluation.
      if (link.nextDep) {
        const next = link.nextDep
        next.prevDep = link.prevDep
        if (link.prevDep) {
          link.prevDep.nextDep = next
        }

        link.prevDep = activeSub.depsTail
        link.nextDep = undefined
        activeSub.depsTail!.nextDep = link
        activeSub.depsTail = link

        // this was the head - point to the new head
        if (activeSub.deps === link) {
          activeSub.deps = next
        }
      }
    }

    if (__DEV__ && activeSub.onTrack) {
      activeSub.onTrack(
        extend(
          {
            effect: activeSub,
          },
          debugInfo,
        ),
      )
    }

    return link
  }

  trigger(debugInfo?: DebuggerEventExtraInfo): void {
    this.version++
    globalVersion++
    this.notify(debugInfo)
  }

  notify(debugInfo?: DebuggerEventExtraInfo): void {
    startBatch()
    try {
      if (__DEV__) {
        // subs are notified and batched in reverse-order and then invoked in
        // original order at the end of the batch, but onTrigger hooks should
        // be invoked in original order here.
        for (let head = this.subsHead; head; head = head.nextSub) {
          if (
            __DEV__ &&
            head.sub.onTrigger &&
            !(head.sub.flags & EffectFlags.NOTIFIED)
          ) {
            head.sub.onTrigger(
              extend(
                {
                  effect: head.sub,
                },
                debugInfo,
              ),
            )
          }
        }
      }
      for (let link = this.subs; link; link = link.prevSub) {
        link.sub.notify()
      }
    } finally {
      endBatch()
    }
  }
}

function addSub(link: Link) {
  const computed = link.dep.computed
  // computed getting its first subscriber
  // enable tracking + lazily subscribe to all its deps
  if (computed && !link.dep.subs) {
    computed.flags |= EffectFlags.TRACKING | EffectFlags.DIRTY
    for (let l = computed.deps; l; l = l.nextDep) {
      addSub(l)
    }
  }

  const currentTail = link.dep.subs
  if (currentTail !== link) {
    link.prevSub = currentTail
    if (currentTail) currentTail.nextSub = link
  }

  if (__DEV__ && link.dep.subsHead === undefined) {
    link.dep.subsHead = link
  }

  link.dep.subs = link
}

export const ITERATE_KEY: unique symbol = Symbol(
  __DEV__ ? 'Object iterate' : '',
)
export const MAP_KEY_ITERATE_KEY: unique symbol = Symbol(
  __DEV__ ? 'Map keys iterate' : '',
)
export const ARRAY_ITERATE_KEY: unique symbol = Symbol(
  __DEV__ ? 'Array iterate' : '',
)

/**
 * Tracks access to a reactive property.
 *
 * This will check which effect is running at the moment and record it as dep
 * which records all effects that depend on the reactive property.
 *
 * @param target - Object holding the reactive property.
 * @param type - Defines the type of access to the reactive property.
 * @param key - Identifier of the reactive property to track.
 */
export function track(target: object, type: TrackOpTypes, key: unknown): void {
  if (shouldTrack && activeSub) {
    ReactiveEffect.runtime.trackReactiveProperty(target, type, key)
  }
}

/**
 * Finds all deps associated with the target (or a specific property) and
 * triggers the effects stored within.
 *
 * @param target - The reactive object.
 * @param type - Defines the type of the operation that needs to trigger effects.
 * @param key - Can be used to target a specific reactive property in the target object.
 */
export function trigger(
  target: object,
  type: TriggerOpTypes,
  key?: unknown,
  newValue?: unknown,
  oldValue?: unknown,
  oldTarget?: Map<unknown, unknown> | Set<unknown>,
): void {
  ReactiveEffect.runtime.triggerReactiveProperty(
    target,
    type,
    key,
    newValue,
    oldValue,
    oldTarget,
  )
}

/**
 * Test only
 */
export function getDepFromReactive(
  object: any,
  key: string | number | symbol,
): Dep | undefined {
  return ReactiveEffect.runtime.getReactiveDep(object, key)
}

import {
  extend,
  hasChanged,
  isArray,
  isIntegerKey,
  isMap,
  isObject,
  isPlainObject,
  isSet,
  isSymbol,
} from '@vue/shared'
import type { ComputedRefImpl } from './computed'
import { ReactiveFlags, type TrackOpTypes, TriggerOpTypes } from './constants'
import {
  ARRAY_ITERATE_KEY,
  Dep,
  ITERATE_KEY,
  MAP_KEY_ITERATE_KEY,
  globalVersion,
  incrementGlobalVersion,
} from './dep'
import { activeEffectScope } from './effectScope'
import { warn } from './warning'

export type EffectScheduler = (...args: any[]) => any

export type DebuggerEvent = {
  effect: Subscriber
} & DebuggerEventExtraInfo

export type DebuggerEventExtraInfo = {
  target: object
  type: TrackOpTypes | TriggerOpTypes
  key: any
  newValue?: any
  oldValue?: any
  oldTarget?: Map<any, any> | Set<any>
}

export interface DebuggerOptions {
  onTrack?: (event: DebuggerEvent) => void
  onTrigger?: (event: DebuggerEvent) => void
}

export interface ReactiveEffectOptions extends DebuggerOptions {
  scheduler?: EffectScheduler
  allowRecurse?: boolean
  onStop?: () => void
}

export interface ReactiveEffectRunner<T = any> {
  (): T
  effect: ReactiveEffect
}

export let activeSub: Subscriber | undefined

export enum EffectFlags {
  ACTIVE = 1 << 0,
  RUNNING = 1 << 1,
  TRACKING = 1 << 2,
  NOTIFIED = 1 << 3,
  DIRTY = 1 << 4,
  ALLOW_RECURSE = 1 << 5,
  NO_BATCH = 1 << 6,
  PAUSED = 1 << 7,
}

/**
 * Subscriber is a type that tracks (or subscribes to) a list of deps.
 */
export interface Subscriber extends DebuggerOptions {
  /**
   * Head of the doubly linked list representing the deps
   * @internal
   */
  deps?: Link
  /**
   * Tail of the same list
   * @internal
   */
  depsTail?: Link
  /**
   * @internal
   */
  flags: EffectFlags
  /**
   * @internal
   */
  notify(): void
}

/**
 * Represents a link between a source (Dep) and a subscriber (Effect or Computed).
 * Deps and subs have a many-to-many relationship - each link between a
 * dep and a sub is represented by a Link instance.
 *
 * A Link is also a node in two doubly-linked lists - one for the associated
 * sub to track all its deps, and one for the associated dep to track all its
 * subs.
 *
 * @internal
 */
export interface Link {
  dep: Dep
  sub: Subscriber

  /**
   * - Before each effect run, all previous dep links' version are reset to -1
   * - During the run, a link's version is synced with the source dep on access
   * - After the run, links with version -1 (that were never used) are cleaned
   *   up
   */
  version: number

  /**
   * Pointers for doubly-linked lists
   */
  nextDep?: Link
  prevDep?: Link

  nextSub?: Link
  prevSub?: Link

  prevActiveLink?: Link
}

const JOB_QUEUED = 1 << 0
const JOB_PRE = 1 << 1
const JOB_ALLOW_RECURSE = 1 << 2
const JOB_DISPOSED = 1 << 3

const pausedQueueEffects = new WeakSet<ReactiveEffect>()

export class ReactiveEffect<T = any>
  implements Subscriber, ReactiveEffectOptions
{
  /**
   * @internal
   */
  deps?: Link = undefined
  /**
   * @internal
   */
  depsTail?: Link = undefined
  /**
   * @internal
   */
  flags: EffectFlags = EffectFlags.ACTIVE | EffectFlags.TRACKING
  /**
   * @internal
   */
  nextEffect?: ReactiveEffect = undefined
  /**
   * @internal
   */
  cleanup?: () => void = undefined

  scheduler?: EffectScheduler = undefined
  onStop?: () => void
  onTrack?: (event: DebuggerEvent) => void
  onTrigger?: (event: DebuggerEvent) => void

  /**
   * @internal
   */
  static runtime: ReactiveEffect<any>

  watchSource: unknown
  watchCallback: ((...args: any[]) => any) | null | undefined
  watchDeep: boolean | number | undefined
  watchForceTrigger: boolean | undefined
  watchMultiSource: boolean | undefined
  watchOldValue: unknown
  watchCleanupFn: (() => void) | undefined
  watchGetter: (() => any) | undefined
  watchInstance: unknown

  watchTraverseSeen: Set<unknown> | undefined
  watchTraverseDepth: number | undefined
  watchTraverseStack: Array<{ depth: number; seen: Set<unknown> }> | undefined
  watchTraverseRoot: unknown

  schedulerQueue: any[] | undefined
  schedulerFlushIndex: number | undefined
  schedulerPendingPost: any[] | undefined
  schedulerActivePost: any[] | null | undefined
  schedulerPostIndex: number | undefined
  schedulerFlushing: boolean | undefined
  schedulerFlushPending: boolean | undefined
  schedulerCurrentPromise: Promise<void> | null | undefined
  schedulerJobRunner: ((job: any) => void) | undefined
  schedulerRecursionCheck: ((job: any, seen: Map<any, number>) => boolean) | undefined
  schedulerSeen: Map<any, number> | undefined
  schedulerResolvedPromise: Promise<any> | undefined

  reactiveTargetMap: WeakMap<object, Map<any, any>> | undefined
  pendingTriggerDeps: any[] | undefined
  lastTriggerTarget: object | undefined
  lastTriggerType: TriggerOpTypes | undefined
  lastTriggerKey: unknown
  lastTrackedTarget: object | undefined

  computedEvalRunning: ComputedRefImpl | undefined
  computedEvalVersion: number | undefined
  computedEvalValue: unknown
  computedEvalPrevSub: Subscriber | undefined
  computedEvalPrevShouldTrack: boolean | undefined
  computedEvalStack:
    | Array<{
        computed: ComputedRefImpl
        prevSub: Subscriber | undefined
        prevShouldTrack: boolean
      }>
    | undefined

  trackingStack: boolean[] | undefined

  installWatchSession(
    source: unknown,
    cb: ((...args: any[]) => any) | null | undefined,
    deep: boolean | number | undefined,
    forceTrigger: boolean,
    isMultiSource: boolean,
    oldValue: unknown,
    instance: unknown,
  ): void {
    this.watchSource = source
    this.watchCallback = cb
    this.watchDeep = deep
    this.watchForceTrigger = forceTrigger
    this.watchMultiSource = isMultiSource
    this.watchOldValue = oldValue
    this.watchInstance = instance
    this.watchCleanupFn = undefined
  }

  bindRefWatchSource(source: { value: unknown }, forceTrigger: boolean): () => unknown {
    this.watchSource = source
    this.watchForceTrigger = forceTrigger
    this.watchMultiSource = false
    const captured = source
    this.watchGetter = () => captured.value
    return this.watchGetter
  }

  bindInvalidWatchSource(
    source: unknown,
    warnInvalid?: (value: unknown) => void,
  ): () => any {
    this.watchSource = source
    this.watchGetter = () => {}
    this.watchForceTrigger = false
    this.watchMultiSource = false
    if (warnInvalid) {
      warnInvalid(source)
    }
    return this.watchGetter
  }

  prepareWatchOldValue(
    isMultiSource: boolean,
    source: unknown,
    token: unknown,
  ): unknown {
    this.watchMultiSource = isMultiSource
    this.watchSource = source
    if (isMultiSource && isArray(source)) {
      this.watchOldValue = new Array((source as unknown[]).length).fill(token)
    } else {
      this.watchOldValue = token
    }
    return this.watchOldValue
  }

  createWatchPathGetter(ctx: any, path: string): () => any {
    this.watchSource = ctx
    const captured = ctx
    const segments = path.split('.')
    this.watchGetter = () => {
      let cur: any = captured
      for (let i = 0; i < segments.length && cur; i++) {
        cur = cur[segments[i]]
      }
      return cur
    }
    return this.watchGetter
  }

  bindReactiveWatchSource(
    source: object,
    deep: boolean | number | undefined,
    shallow: boolean = false,
  ): () => unknown {
    this.watchSource = source
    this.watchDeep = deep
    this.watchForceTrigger = true
    this.watchMultiSource = false
    const captured = source
    const capturedDeep = deep
    const capturedShallow = shallow
    this.watchGetter = () =>
      this.wrapReactiveWatchGetter(captured, capturedDeep, capturedShallow)
    return this.watchGetter
  }

  wrapReactiveWatchGetter(
    source: object,
    deep: boolean | number | undefined = this.watchDeep,
    shallow: boolean = false,
  ): unknown {
    this.watchSource = source
    this.watchDeep = deep
    if (deep) {
      this.watchTraverseDepth = typeof deep === 'number' ? deep : Infinity
      return source
    }
    if (shallow || deep === false || deep === 0) {
      this.watchTraverseDepth = 1
      return this.traverseWatchValue(source, 1)
    }
    this.watchTraverseDepth = Infinity
    return this.traverseWatchValue(source, Infinity)
  }

  bindMultiWatchSource(
    source: unknown[],
    deep: boolean | number | undefined,
    readSource: (item: unknown) => unknown,
  ): () => unknown[] {
    this.watchSource = source
    this.watchDeep = deep
    this.watchMultiSource = true
    const captured = source
    this.watchGetter = () => {
      const items = captured
      const values: unknown[] = []
      for (let i = 0; i < items.length; i++) {
        values.push(readSource(items[i]))
      }
      return values
    }
    return this.watchGetter as () => unknown[]
  }

  bindFunctionWatchSource(
    source: (...args: any[]) => any,
    hasCallback: boolean,
    runGetter: (fn: (...args: any[]) => any) => any,
    runEffect: (fn: (...args: any[]) => any, args: any[]) => any,
    onCleanup: (fn: () => void) => void,
  ): () => any {
    this.watchSource = source
    this.watchGetter = hasCallback
      ? () => runGetter(source)
      : () => {
          if (this.watchCleanupFn) {
            this.watchCleanupFn()
          }
          return runEffect(source, [onCleanup])
        }
    return this.watchGetter
  }

  wrapWatchDeepGetter(baseGetter: () => any, deep: boolean | number): () => any {
    this.watchDeep = deep
    this.watchGetter = baseGetter
    const depth = deep === true ? Infinity : deep
    this.watchTraverseDepth = depth
    const getter = baseGetter
    return () => {
      this.watchTraverseDepth = depth
      const value = getter()
      return this.traverseWatchValue(value, depth)
    }
  }

  wrapCompatArrayWatchGetter(
    baseGetter: () => any,
    shouldTraverse: (value: unknown) => boolean,
  ): () => any {
    this.watchGetter = baseGetter
    const getter = baseGetter
    return () => {
      const val = getter()
      if (isArray(val) && shouldTraverse(val)) {
        this.traverseWatchValue(val)
      }
      return val
    }
  }

  shouldDispatchWatchValue(newValue: unknown, extraTrigger: boolean = false): boolean {
    const oldValue = this.watchOldValue
    if (this.watchDeep || this.watchForceTrigger || extraTrigger) {
      return true
    }
    if (this.watchMultiSource) {
      const next = newValue as any[]
      const prev = oldValue as any[]
      if (!isArray(next) || !isArray(prev) || next.length !== prev.length) {
        return true
      }
      for (let i = 0; i < next.length; i++) {
        if (hasChanged(next[i], prev[i])) {
          return true
        }
      }
      return false
    }
    return hasChanged(newValue, oldValue)
  }

  commitWatchOldValue(newValue: unknown): unknown {
    this.watchOldValue = newValue
    if (this.watchMultiSource && !isArray(this.watchOldValue)) {
      this.watchOldValue = newValue
    }
    return this.watchOldValue
  }

  attachWatchCleanup(
    cleanup: () => void,
    bindStop: (stop: () => void) => void,
  ): void {
    this.watchCleanupFn = () => {
      cleanup()
      this.watchCleanupFn = undefined
    }
    bindStop(this.watchCleanupFn)
  }

  readWatchOldValue(initialToken: unknown): unknown {
    const oldValue = this.watchOldValue
    if (oldValue === initialToken) {
      return undefined
    }
    if (
      this.watchMultiSource &&
      isArray(oldValue) &&
      oldValue.length > 0 &&
      oldValue[0] === initialToken
    ) {
      return []
    }
    return oldValue
  }

  beginWatchTraverse(depth: number, seen?: Set<unknown>): Set<unknown> {
    const stack = this.watchTraverseStack || (this.watchTraverseStack = [])
    const resolved =
      seen ||
      (stack.length > 0 ? stack[stack.length - 1].seen : new Set<unknown>())
    this.watchTraverseSeen = resolved
    this.watchTraverseDepth = depth
    stack.push({ depth, seen: resolved })
    return resolved
  }

  endWatchTraverse(): void {
    const stack = this.watchTraverseStack
    if (stack && stack.length) {
      stack.pop()
      const parent = stack[stack.length - 1]
      this.watchTraverseDepth = parent ? parent.depth : undefined
      this.watchTraverseSeen = parent ? parent.seen : undefined
    } else {
      this.watchTraverseDepth = undefined
      this.watchTraverseSeen = undefined
    }
  }

  traverseWatchValue(
    value: unknown,
    depth: number = Infinity,
    seen?: Set<unknown>,
  ): unknown {
    this.watchTraverseRoot = value
    this.watchTraverseDepth = depth
    if (
      depth <= 0 ||
      !isObject(value) ||
      (value as any)[ReactiveFlags.SKIP]
    ) {
      return value
    }
    const currentSeen = this.beginWatchTraverse(depth, seen)
    this.watchTraverseSeen = currentSeen
    if (currentSeen.has(value)) {
      this.endWatchTraverse()
      return value
    }
    currentSeen.add(value)
    try {
      return this.walkWatchTraverse(value, depth - 1, currentSeen)
    } finally {
      this.endWatchTraverse()
    }
  }

  walkWatchTraverse(
    value: object,
    depth: number,
    seen: Set<unknown>,
  ): unknown {
    this.watchTraverseSeen = seen
    this.watchTraverseDepth = depth
    if ((value as any)[ReactiveFlags.IS_REF] === true) {
      this.traverseWatchValue((value as any).value, depth, seen)
      return value
    }
    if (isArray(value)) {
      this.traverseWatchRecord(value, depth, seen)
      return value
    }
    if (isSet(value) || isMap(value)) {
      this.traverseWatchCollection(value, depth, seen)
      return value
    }
    if (isPlainObject(value)) {
      this.traverseWatchPlainObject(value, depth, seen)
      return value
    }
    return value
  }

  traverseWatchRecord(
    value: unknown[],
    depth: number,
    seen: Set<unknown>,
  ): void {
    this.watchTraverseSeen = seen
    this.watchTraverseDepth = depth
    for (let i = 0; i < value.length; i++) {
      this.traverseWatchValue(value[i], depth, seen)
    }
  }

  traverseWatchCollection(
    value: Set<any> | Map<any, any>,
    depth: number,
    seen: Set<unknown>,
  ): void {
    this.watchTraverseSeen = seen
    this.watchTraverseDepth = depth
    value.forEach((v: any) => {
      this.traverseWatchValue(v, depth, seen)
    })
  }

  traverseWatchPlainObject(
    value: Record<string | symbol, any>,
    depth: number,
    seen: Set<unknown>,
  ): void {
    this.watchTraverseSeen = seen
    this.watchTraverseDepth = depth
    for (const key in value) {
      this.traverseWatchValue(value[key], depth, seen)
    }
    const symbols = Object.getOwnPropertySymbols(value)
    for (let i = 0; i < symbols.length; i++) {
      const key = symbols[i]
      if (Object.prototype.propertyIsEnumerable.call(value, key)) {
        this.traverseWatchValue(value[key as any], depth, seen)
      }
    }
  }

  attachSchedulerRunner(
    runJob: (job: any) => void,
    checkRecursive?: (job: any, seen: Map<any, number>) => boolean,
  ): void {
    this.schedulerJobRunner = runJob
    this.schedulerRecursionCheck = checkRecursive
    if (!this.schedulerQueue) this.schedulerQueue = []
    if (this.schedulerFlushIndex == null) this.schedulerFlushIndex = 0
    if (!this.schedulerPendingPost) this.schedulerPendingPost = []
    if (this.schedulerActivePost === undefined) this.schedulerActivePost = null
    if (this.schedulerPostIndex == null) this.schedulerPostIndex = 0
    if (this.schedulerFlushing == null) this.schedulerFlushing = false
    if (this.schedulerFlushPending == null) this.schedulerFlushPending = false
    if (this.schedulerCurrentPromise === undefined) {
      this.schedulerCurrentPromise = null
    }
    if (!this.schedulerResolvedPromise) {
      this.schedulerResolvedPromise = Promise.resolve() as Promise<any>
    }
    if (!this.schedulerSeen) {
      this.schedulerSeen = new Map()
    }
    if (this.schedulerFlushIndex == null || this.schedulerFlushIndex < 0) {
      this.schedulerFlushIndex = 0
    }
  }

  enqueueSchedulerJob(job: any): void {
    const queue = this.schedulerQueue || (this.schedulerQueue = [])
    if (job.flags! & JOB_QUEUED) {
      return
    }
    if (job.id == null) {
      queue.push(job)
    } else if (
      !(job.flags! & JOB_PRE) &&
      job.id >= ((queue[queue.length - 1] && queue[queue.length - 1].id) || 0)
    ) {
      queue.push(job)
    } else {
      queue.splice(this.findSchedulerInsertionIndex(job.id), 0, job)
    }
    if (!(job.flags! & JOB_ALLOW_RECURSE)) {
      job.flags! |= JOB_QUEUED
    }
    this.queueSchedulerFlush()
  }

  findSchedulerInsertionIndex(id: number): number {
    const queue = this.schedulerQueue || (this.schedulerQueue = [])
    const flushIndex = this.schedulerFlushIndex || 0
    let start = flushIndex + 1
    let end = queue.length
    while (start < end) {
      const middle = (start + end) >>> 1
      const middleJob = queue[middle]
      const middleJobId = this.getSchedulerJobId(middleJob)
      if (
        middleJobId < id ||
        (middleJobId === id && middleJob.flags! & JOB_PRE)
      ) {
        start = middle + 1
      } else {
        end = middle
      }
    }
    return start
  }

  getSchedulerJobId(job: any): number {
    const queue = this.schedulerQueue
    if (!queue) {
      return job && job.id == null ? Infinity : job.id
    }
    return job && job.id == null ? Infinity : job.id
  }

  queueSchedulerFlush(): void {
    if (!this.schedulerFlushing && !this.schedulerFlushPending) {
      this.schedulerFlushPending = true
      const resolved =
        this.schedulerResolvedPromise ||
        (this.schedulerResolvedPromise = Promise.resolve() as Promise<any>)
      this.schedulerCurrentPromise = resolved.then(() =>
        this.flushSchedulerQueue(),
      )
    }
  }

  invalidateSchedulerJob(job: any): void {
    const queue = this.schedulerQueue
    if (!queue || !queue.length) {
      return
    }
    const i = queue.indexOf(job)
    const flushIndex = this.schedulerFlushIndex || 0
    if (i > flushIndex) {
      queue.splice(i, 1)
    }
  }

  enqueuePostFlushCallback(cb: any): void {
    const pending = this.schedulerPendingPost || (this.schedulerPendingPost = [])
    if (!isArray(cb)) {
      if (this.schedulerActivePost && cb.id === -1) {
        this.schedulerActivePost.splice((this.schedulerPostIndex || 0) + 1, 0, cb)
      } else if (!(cb.flags! & JOB_QUEUED)) {
        pending.push(cb)
        if (!(cb.flags! & JOB_ALLOW_RECURSE)) {
          cb.flags! |= JOB_QUEUED
        }
      }
    } else {
      pending.push(...cb)
    }
    this.queueSchedulerFlush()
  }

  flushPreFlushJobs(instance?: any, seen?: Map<any, number>, startIndex?: number): void {
    const queue = this.schedulerQueue || (this.schedulerQueue = [])
    if (__DEV__) {
      seen = seen || this.schedulerSeen || (this.schedulerSeen = new Map())
    }
    let i =
      startIndex != null
        ? startIndex
        : this.schedulerFlushing
          ? (this.schedulerFlushIndex || 0) + 1
          : 0
    for (; i < queue.length; i++) {
      const cb = queue[i]
      if (cb && cb.flags! & JOB_PRE) {
        if (instance && cb.id !== instance.uid) {
          continue
        }
        if (
          __DEV__ &&
          this.schedulerRecursionCheck &&
          this.schedulerRecursionCheck(cb, seen!)
        ) {
          continue
        }
        queue.splice(i, 1)
        i--
        cb()
        cb.flags! &= ~JOB_QUEUED
      }
    }
  }

  flushPostFlushJobs(seen?: Map<any, number>): void {
    const pending = this.schedulerPendingPost || (this.schedulerPendingPost = [])
    if (!pending.length) {
      return
    }
    const deduped = [...new Set(pending)].sort(
      (a, b) => this.getSchedulerJobId(a) - this.getSchedulerJobId(b),
    )
    pending.length = 0
    if (this.schedulerActivePost) {
      this.schedulerActivePost.push(...deduped)
      return
    }
    this.schedulerActivePost = deduped
    if (__DEV__) {
      seen = seen || this.schedulerSeen || (this.schedulerSeen = new Map())
    }
    for (
      this.schedulerPostIndex = 0;
      this.schedulerPostIndex < this.schedulerActivePost.length;
      this.schedulerPostIndex++
    ) {
      const cb = this.schedulerActivePost[this.schedulerPostIndex]
      if (
        __DEV__ &&
        this.schedulerRecursionCheck &&
        this.schedulerRecursionCheck(cb, seen!)
      ) {
        continue
      }
      if (!(cb.flags! & JOB_DISPOSED)) cb()
      cb.flags! &= ~JOB_QUEUED
    }
    this.schedulerActivePost = null
    this.schedulerPostIndex = 0
  }

  compareSchedulerJobs(a: any, b: any): number {
    const queue = this.schedulerQueue
    const diff = this.getSchedulerJobId(a) - this.getSchedulerJobId(b)
    if (diff === 0) {
      const isAPre = a.flags! & JOB_PRE
      const isBPre = b.flags! & JOB_PRE
      if (isAPre && !isBPre) return -1
      if (isBPre && !isAPre) return 1
      if (queue && queue.length === 0) return 0
    }
    return diff
  }

  flushSchedulerQueue(seen?: Map<any, number>): void {
    this.schedulerFlushPending = false
    this.schedulerFlushing = true
    const queue = this.schedulerQueue || (this.schedulerQueue = [])
    if (__DEV__) {
      seen = seen || this.schedulerSeen || (this.schedulerSeen = new Map())
      this.schedulerSeen = seen
    }
    queue.sort((a, b) => this.compareSchedulerJobs(a, b))
    const runner = this.schedulerJobRunner
    const check = this.schedulerRecursionCheck
    try {
      for (
        this.schedulerFlushIndex = 0;
        this.schedulerFlushIndex < queue.length;
        this.schedulerFlushIndex++
      ) {
        const job = queue[this.schedulerFlushIndex]
        if (job && !(job.flags! & JOB_DISPOSED)) {
          if (__DEV__ && check && check(job, seen!)) {
            continue
          }
          if (runner) {
            runner(job)
          } else {
            job()
          }
          job.flags! &= ~JOB_QUEUED
        }
      }
    } finally {
      this.schedulerFlushIndex = 0
      queue.length = 0
      this.flushPostFlushJobs(seen)
      this.schedulerFlushing = false
      this.schedulerCurrentPromise = null
      if (
        queue.length ||
        (this.schedulerPendingPost && this.schedulerPendingPost.length)
      ) {
        this.flushSchedulerQueue(seen)
      }
    }
  }

  getSchedulerFlushPromise(): Promise<void> | null {
    const queue = this.schedulerQueue
    if (!queue || queue.length === 0) {
      return this.schedulerCurrentPromise || null
    }
    if (this.schedulerFlushing || this.schedulerFlushPending) {
      return this.schedulerCurrentPromise || null
    }
    return this.schedulerCurrentPromise || null
  }

  ensureReactiveDep(target: object, key: unknown): Dep {
    const targetMap =
      this.reactiveTargetMap || (this.reactiveTargetMap = new WeakMap())
    this.lastTrackedTarget = target
    let depsMap = targetMap.get(target)
    if (!depsMap) {
      targetMap.set(target, (depsMap = new Map()))
    }
    let dep = depsMap.get(key)
    if (!dep) {
      depsMap.set(key, (dep = new Dep()))
    }
    return dep
  }

  getReactiveDep(target: object, key: unknown): Dep | undefined {
    const targetMap = this.reactiveTargetMap
    this.lastTrackedTarget = target
    if (!targetMap) {
      return undefined
    }
    const depsMap = targetMap.get(target)
    if (!depsMap) {
      return undefined
    }
    if (!depsMap.has(key)) {
      return undefined
    }
    return depsMap.get(key)
  }

  trackReactiveProperty(
    target: object,
    type: TrackOpTypes,
    key: unknown,
  ): void {
    const dep = this.ensureReactiveDep(target, key)
    this.lastTrackedTarget = target
    if (__DEV__) {
      dep.track({
        target,
        type,
        key,
      })
    } else {
      dep.track()
    }
  }

  collectArrayLengthDeps(
    depsMap: Map<any, any>,
    newValue: unknown,
    deps: any[],
  ): void {
    this.pendingTriggerDeps = deps
    const newLength = Number(newValue)
    depsMap.forEach((dep, key) => {
      if (
        key === 'length' ||
        key === ARRAY_ITERATE_KEY ||
        (!isSymbol(key) && key >= newLength)
      ) {
        deps.push(dep)
      }
    })
  }

  collectIterateDeps(
    depsMap: Map<any, any>,
    target: object,
    type: TriggerOpTypes,
    key: unknown,
    targetIsArray: boolean,
    isArrayIndex: boolean,
    deps: any[],
  ): void {
    this.pendingTriggerDeps = deps
    this.lastTriggerType = type
    this.lastTriggerKey = key
    const push = (dep: Dep | undefined): void => {
      if (dep) deps.push(dep)
    }
    if (key !== void 0) {
      push(depsMap.get(key))
    }
    if (isArrayIndex) {
      push(depsMap.get(ARRAY_ITERATE_KEY))
    }
    switch (type) {
      case TriggerOpTypes.ADD:
        if (!targetIsArray) {
          push(depsMap.get(ITERATE_KEY))
          if (isMap(target)) {
            push(depsMap.get(MAP_KEY_ITERATE_KEY))
          }
        } else if (isArrayIndex) {
          push(depsMap.get('length'))
        }
        break
      case TriggerOpTypes.DELETE:
        if (!targetIsArray) {
          push(depsMap.get(ITERATE_KEY))
          if (isMap(target)) {
            push(depsMap.get(MAP_KEY_ITERATE_KEY))
          }
        }
        break
      case TriggerOpTypes.SET:
        if (isMap(target)) {
          push(depsMap.get(ITERATE_KEY))
        }
        break
    }
  }

  collectTriggerDeps(
    target: object,
    type: TriggerOpTypes,
    key?: unknown,
    newValue?: unknown,
  ): any[] {
    const targetMap = this.reactiveTargetMap
    this.lastTriggerTarget = target
    this.lastTriggerType = type
    this.lastTriggerKey = key
    const deps: any[] = []
    this.pendingTriggerDeps = deps
    if (!targetMap) {
      this.pendingTriggerDeps = deps
      return deps
    }
    const depsMap = targetMap.get(target)
    if (!depsMap) {
      this.lastTriggerTarget = target
      this.pendingTriggerDeps = deps
      return deps
    }
    if (type === TriggerOpTypes.CLEAR) {
      deps.push(...depsMap.values())
      return deps
    }
    const targetIsArray = isArray(target)
    const isArrayIndex = targetIsArray && isIntegerKey(key)
    if (targetIsArray && key === 'length') {
      this.collectArrayLengthDeps(depsMap, newValue, deps)
    } else {
      this.collectIterateDeps(
        depsMap,
        target,
        type,
        key,
        targetIsArray,
        !!isArrayIndex,
        deps,
      )
    }
    return deps
  }

  triggerReactiveProperty(
    target: object,
    type: TriggerOpTypes,
    key?: unknown,
    newValue?: unknown,
    oldValue?: unknown,
    oldTarget?: Map<unknown, unknown> | Set<unknown>,
  ): void {
    const targetMap = this.reactiveTargetMap
    this.lastTriggerTarget = target
    this.lastTriggerType = type
    this.lastTriggerKey = key
    if (!targetMap) {
      incrementGlobalVersion()
      return
    }
    if (!targetMap.get(target)) {
      incrementGlobalVersion()
      return
    }
    const deps = this.collectTriggerDeps(target, type, key, newValue)
    this.pendingTriggerDeps = deps
    startBatch()
    for (let i = 0; i < deps.length; i++) {
      const dep = deps[i]
      if (__DEV__) {
        dep.trigger({
          target,
          type,
          key,
          newValue,
          oldValue,
          oldTarget,
        })
      } else {
        dep.trigger()
      }
    }
    endBatch()
  }

  shouldSkipComputedRefresh(computed: ComputedRefImpl): boolean | 'false' {
    this.computedEvalRunning = computed
    this.computedEvalVersion = computed.globalVersion
    if (computed.flags & EffectFlags.RUNNING) {
      return 'false'
    }
    if (
      computed.flags & EffectFlags.TRACKING &&
      !(computed.flags & EffectFlags.DIRTY)
    ) {
      return true
    }
    return false
  }

  beginComputedEvaluation(computed: ComputedRefImpl): boolean {
    this.computedEvalRunning = computed
    computed.flags &= ~EffectFlags.DIRTY
    this.computedEvalVersion = computed.globalVersion
    if (computed.globalVersion === globalVersion) {
      return false
    }
    computed.globalVersion = globalVersion
    this.computedEvalVersion = computed.globalVersion
    const dep = computed.dep
    computed.flags |= EffectFlags.RUNNING
    if (dep.version > 0 && !computed.isSSR && !isDirty(computed)) {
      computed.flags &= ~EffectFlags.RUNNING
      return false
    }
    const stack = this.computedEvalStack || (this.computedEvalStack = [])
    stack.push({
      computed,
      prevSub: activeSub,
      prevShouldTrack: shouldTrack,
    })
    this.computedEvalPrevSub = activeSub
    this.computedEvalPrevShouldTrack = shouldTrack
    activeSub = computed
    shouldTrack = true
    return true
  }

  writeComputedResult(computed: ComputedRefImpl, value: unknown): void {
    this.computedEvalRunning = computed
    this.computedEvalValue = value
    const dep = computed.dep
    if (dep.version === 0 || hasChanged(value, computed._value)) {
      computed._value = value
      this.computedEvalValue = computed._value
      dep.version++
    }
  }

  finishComputedEvaluation(computed: ComputedRefImpl): void {
    const stack = this.computedEvalStack
    const frame = stack && stack.length ? stack.pop() : undefined
    const prevSub = frame ? frame.prevSub : this.computedEvalPrevSub
    const prevShouldTrack = frame ? frame.prevShouldTrack : this.computedEvalPrevShouldTrack
    this.computedEvalRunning = computed
    activeSub = prevSub
    shouldTrack = prevShouldTrack === undefined ? shouldTrack : prevShouldTrack
    cleanupDeps(computed)
    computed.flags &= ~EffectFlags.RUNNING
    const parent = stack && stack.length ? stack[stack.length - 1] : undefined
    this.computedEvalPrevSub = parent ? parent.prevSub : undefined
    this.computedEvalPrevShouldTrack = parent ? parent.prevShouldTrack : undefined
    this.computedEvalRunning = parent ? parent.computed : undefined
  }

  refreshComputedValue(computed: ComputedRefImpl): false | undefined {
    this.computedEvalRunning = computed
    const skip = this.shouldSkipComputedRefresh(computed)
    if (skip === 'false') {
      return false
    }
    if (skip) {
      return
    }
    if (!this.beginComputedEvaluation(computed)) {
      return
    }
    const dep = computed.dep
    try {
      prepareDeps(computed)
      const value = computed.fn()
      this.writeComputedResult(computed, value)
    } catch (err) {
      dep.version++
      throw err
    } finally {
      this.finishComputedEvaluation(computed)
    }
  }

  ensureTrackingStack(): boolean[] {
    return this.trackingStack || (this.trackingStack = [])
  }

  pauseEffectTracking(): void {
    const stack = this.ensureTrackingStack()
    stack.push(shouldTrack)
    shouldTrack = false
  }

  enableEffectTracking(): void {
    const stack = this.ensureTrackingStack()
    stack.push(shouldTrack)
    shouldTrack = true
  }

  resetEffectTracking(): void {
    const stack = this.ensureTrackingStack()
    const last = stack.pop()
    shouldTrack = last === undefined ? true : last
  }


  constructor(public fn: () => T) {
    if (activeEffectScope && activeEffectScope.active) {
      activeEffectScope.effects.push(this)
    }
  }

  pause(): void {
    this.flags |= EffectFlags.PAUSED
  }

  resume(): void {
    if (this.flags & EffectFlags.PAUSED) {
      this.flags &= ~EffectFlags.PAUSED
      if (pausedQueueEffects.has(this)) {
        pausedQueueEffects.delete(this)
        this.trigger()
      }
    }
  }

  /**
   * @internal
   */
  notify(): void {
    if (
      this.flags & EffectFlags.RUNNING &&
      !(this.flags & EffectFlags.ALLOW_RECURSE)
    ) {
      return
    }
    if (this.flags & EffectFlags.NO_BATCH) {
      return this.trigger()
    }
    if (!(this.flags & EffectFlags.NOTIFIED)) {
      this.flags |= EffectFlags.NOTIFIED
      this.nextEffect = batchedEffect
      batchedEffect = this
    }
  }

  run(): T {
    // TODO cleanupEffect

    if (!(this.flags & EffectFlags.ACTIVE)) {
      // stopped during cleanup
      return this.fn()
    }

    this.flags |= EffectFlags.RUNNING
    cleanupEffect(this)
    prepareDeps(this)
    const prevEffect = activeSub
    const prevShouldTrack = shouldTrack
    activeSub = this
    shouldTrack = true

    try {
      return this.fn()
    } finally {
      if (__DEV__ && activeSub !== this) {
        warn(
          'Active effect was not restored correctly - ' +
            'this is likely a Vue internal bug.',
        )
      }
      cleanupDeps(this)
      activeSub = prevEffect
      shouldTrack = prevShouldTrack
      this.flags &= ~EffectFlags.RUNNING
    }
  }

  stop(): void {
    if (this.flags & EffectFlags.ACTIVE) {
      for (let link = this.deps; link; link = link.nextDep) {
        removeSub(link)
      }
      this.deps = this.depsTail = undefined
      cleanupEffect(this)
      this.onStop && this.onStop()
      this.flags &= ~EffectFlags.ACTIVE
    }
  }

  trigger(): void {
    if (this.flags & EffectFlags.PAUSED) {
      pausedQueueEffects.add(this)
    } else if (this.scheduler) {
      this.scheduler()
    } else {
      this.runIfDirty()
    }
  }

  /**
   * @internal
   */
  runIfDirty(): void {
    if (isDirty(this)) {
      this.run()
    }
  }

  get dirty(): boolean {
    return isDirty(this)
  }
}

ReactiveEffect.runtime = new ReactiveEffect(() => {})

let batchDepth = 0
let batchedEffect: ReactiveEffect | undefined

/**
 * @internal
 */
export function startBatch(): void {
  batchDepth++
}

/**
 * Run batched effects when all batches have ended
 * @internal
 */
export function endBatch(): void {
  if (batchDepth > 1) {
    batchDepth--
    return
  }

  let error: unknown
  while (batchedEffect) {
    let e: ReactiveEffect | undefined = batchedEffect
    batchedEffect = undefined
    while (e) {
      const next: ReactiveEffect | undefined = e.nextEffect
      e.nextEffect = undefined
      e.flags &= ~EffectFlags.NOTIFIED
      if (e.flags & EffectFlags.ACTIVE) {
        try {
          e.trigger()
        } catch (err) {
          if (!error) error = err
        }
      }
      e = next
    }
  }

  batchDepth--
  if (error) throw error
}

function prepareDeps(sub: Subscriber) {
  // Prepare deps for tracking, starting from the head
  for (let link = sub.deps; link; link = link.nextDep) {
    // set all previous deps' (if any) version to -1 so that we can track
    // which ones are unused after the run
    link.version = -1
    // store previous active sub if link was being used in another context
    link.prevActiveLink = link.dep.activeLink
    link.dep.activeLink = link
  }
}

function cleanupDeps(sub: Subscriber) {
  // Cleanup unsued deps
  let head
  let tail = sub.depsTail
  for (let link = tail; link; link = link.prevDep) {
    if (link.version === -1) {
      if (link === tail) tail = link.prevDep
      // unused - remove it from the dep's subscribing effect list
      removeSub(link)
      // also remove it from this effect's dep list
      removeDep(link)
    } else {
      // The new head is the last node seen which wasn't removed
      // from the doubly-linked list
      head = link
    }

    // restore previous active link if any
    link.dep.activeLink = link.prevActiveLink
    link.prevActiveLink = undefined
  }
  // set the new head & tail
  sub.deps = head
  sub.depsTail = tail
}

function isDirty(sub: Subscriber): boolean {
  for (let link = sub.deps; link; link = link.nextDep) {
    if (
      link.dep.version !== link.version ||
      (link.dep.computed && refreshComputed(link.dep.computed) === false) ||
      link.dep.version !== link.version
    ) {
      return true
    }
  }
  // @ts-expect-error only for backwards compatibility where libs manually set
  // this flag - e.g. Pinia's testing module
  if (sub._dirty) {
    return true
  }
  return false
}

/**
 * Returning false indicates the refresh failed
 * @internal
 */
export function refreshComputed(computed: ComputedRefImpl): false | undefined {
  return ReactiveEffect.runtime.refreshComputedValue(computed)
}

function removeSub(link: Link) {
  const { dep, prevSub, nextSub } = link
  if (prevSub) {
    prevSub.nextSub = nextSub
    link.prevSub = undefined
  }
  if (nextSub) {
    nextSub.prevSub = prevSub
    link.nextSub = undefined
  }
  if (dep.subs === link) {
    // was previous tail, point new tail to prev
    dep.subs = prevSub
  }

  if (!dep.subs && dep.computed) {
    // last subscriber removed
    // if computed, unsubscribe it from all its deps so this computed and its
    // value can be GCed
    dep.computed.flags &= ~EffectFlags.TRACKING
    for (let l = dep.computed.deps; l; l = l.nextDep) {
      removeSub(l)
    }
  }
}

function removeDep(link: Link) {
  const { prevDep, nextDep } = link
  if (prevDep) {
    prevDep.nextDep = nextDep
    link.prevDep = undefined
  }
  if (nextDep) {
    nextDep.prevDep = prevDep
    link.nextDep = undefined
  }
}

export interface ReactiveEffectRunner<T = any> {
  (): T
  effect: ReactiveEffect
}

export function effect<T = any>(
  fn: () => T,
  options?: ReactiveEffectOptions,
): ReactiveEffectRunner<T> {
  if ((fn as ReactiveEffectRunner).effect instanceof ReactiveEffect) {
    fn = (fn as ReactiveEffectRunner).effect.fn
  }

  const e = new ReactiveEffect(fn)
  if (options) {
    extend(e, options)
  }
  try {
    e.run()
  } catch (err) {
    e.stop()
    throw err
  }
  const runner = e.run.bind(e) as ReactiveEffectRunner
  runner.effect = e
  return runner
}

/**
 * Stops the effect associated with the given runner.
 *
 * @param runner - Association with the effect to stop tracking.
 */
export function stop(runner: ReactiveEffectRunner): void {
  runner.effect.stop()
}

/**
 * @internal
 */
export let shouldTrack = true

/**
 * Temporarily pauses tracking.
 */
export function pauseTracking(): void {
  ReactiveEffect.runtime.pauseEffectTracking()
}

/**
 * Re-enables effect tracking (if it was paused).
 */
export function enableTracking(): void {
  ReactiveEffect.runtime.enableEffectTracking()
}

/**
 * Resets the previous global effect tracking state.
 */
export function resetTracking(): void {
  ReactiveEffect.runtime.resetEffectTracking()
}

/**
 * Registers a cleanup function for the current active effect.
 * The cleanup function is called right before the next effect run, or when the
 * effect is stopped.
 *
 * Throws a warning iff there is no currenct active effect. The warning can be
 * suppressed by passing `true` to the second argument.
 *
 * @param fn - the cleanup function to be registered
 * @param failSilently - if `true`, will not throw warning when called without
 * an active effect.
 */
export function onEffectCleanup(fn: () => void, failSilently = false): void {
  if (activeSub instanceof ReactiveEffect) {
    activeSub.cleanup = fn
  } else if (__DEV__ && !failSilently) {
    warn(
      `onEffectCleanup() was called when there was no active effect` +
        ` to associate with.`,
    )
  }
}

function cleanupEffect(e: ReactiveEffect) {
  const { cleanup } = e
  e.cleanup = undefined
  if (cleanup) {
    // run cleanup without active effect
    const prevSub = activeSub
    activeSub = undefined
    try {
      cleanup()
    } finally {
      activeSub = prevSub
    }
  }
}

import { isFunction } from '@vue/shared'
import {
  type DebuggerEvent,
  type DebuggerOptions,
  EffectFlags,
  type Link,
  type Subscriber,
  activeSub,
  refreshComputed,
} from './effect'
import type { Ref } from './ref'
import { warn } from './warning'
import { Dep, globalVersion } from './dep'
import { ReactiveFlags, TrackOpTypes } from './constants'

declare const ComputedRefSymbol: unique symbol

export interface ComputedRef<T = any> extends WritableComputedRef<T> {
  readonly value: T
  [ComputedRefSymbol]: true
}

export interface WritableComputedRef<T, S = T> extends Ref<T, S> {
  /**
   * @deprecated computed no longer uses effect
   */
  effect: ComputedRefImpl
}

export type ComputedGetter<T> = (oldValue?: T) => T
export type ComputedSetter<T> = (newValue: T) => void

export interface WritableComputedOptions<T, S = T> {
  get: ComputedGetter<T>
  set: ComputedSetter<S>
}

/**
 * @private exported by @vue/reactivity for Vue core use, but not exported from
 * the main vue package
 */
export class ComputedRefImpl<T = any> implements Subscriber {
  /**
   * @internal
   */
  _value: any = undefined
  /**
   * @internal
   */
  readonly dep: Dep = new Dep(this)
  /**
   * @internal
   */
  readonly __v_isRef = true
  // TODO isolatedDeclarations ReactiveFlags.IS_REF
  /**
   * @internal
   */
  readonly __v_isReadonly: boolean
  // TODO isolatedDeclarations ReactiveFlags.IS_READONLY
  // A computed is also a subscriber that tracks other deps
  /**
   * @internal
   */
  deps?: Link = undefined
  /**
   * @internal
   */
  depsTail?: Link = undefined
  /**
   * @internal
   */
  flags: EffectFlags = EffectFlags.DIRTY
  /**
   * @internal
   */
  globalVersion: number = globalVersion - 1
  /**
   * @internal
   */
  isSSR: boolean
  // for backwards compat
  effect: this = this

  // dev only
  onTrack?: (event: DebuggerEvent) => void
  // dev only
  onTrigger?: (event: DebuggerEvent) => void

  /**
   * Dev only
   * @internal
   */
  _warnRecursive?: boolean

  constructor(
    public fn: ComputedGetter<T>,
    private readonly setter: ComputedSetter<T> | undefined,
    isSSR: boolean,
  ) {
