import { ref, computed, watch } from "../src/index"
describe("scratch order", () => {
  test("ref sync order", () => {
    const n = ref(0)
    const order: number[] = []
    for (let i = 0; i < 5; i++) {
      watch(n, () => { order.push(i) }, { flush: "sync" })
    }
    n.value++
    expect(order).toEqual([0, 1, 2, 3, 4])
  })
  test("computed sync order", () => {
    const n = ref(0)
    const c = computed(() => n.value)
    const order: number[] = []
    for (let i = 0; i < 5; i++) {
      watch(c, () => { order.push(i) }, { flush: "sync" })
    }
    n.value++
    expect(order).toEqual([0, 1, 2, 3, 4])
  })
})
EOF
