let syncSubs: Subscriber[] | undefined
for (let link = this.subs; link; link = link.prevSub) {
  if (link.sub.flags & EffectFlags.NO_BATCH) {
    ;(syncSubs || (syncSubs = [])).push(link.sub)
  } else {
    link.sub.notify()
  }
}
if (syncSubs) {
  for (let i = syncSubs.length - 1; i >= 0; i--) {
    syncSubs[i].notify()
  }
}

